FamilyTree.person({"id":"elodia","name":"Elodia Octavia Bostyn","dates":"1908 – 1997 Oostende","confidence":"sup","surname":"Bostyn","family":"bostyn","born":"1908","order":"1908","died":"1997 Oostende","occupation":"werkster (labourer)","branch":"Bundervoet","line":"bundervoet","father":"henricus_bostyn","mother":"judith_cappaert","spouses":[{"id":"alphonsus","name":"Alphonsus Bernardus Bundervoet"}],"source":"Familiekunde Vlaanderen Westkust memorial card — Alfons Bundervoet, d. Oostende 11 Mar 1980; Geneanet","note":"Source detail: Fauconier tree (Geneanet); Oostende marriage act 334, 1930\n\nMarcel’s mother. Oostende birth act 1013/1908. Her Bostyn/Cappaert family came from the Bruges area (Varsenare, Oostkamp).\n\nCORROBORATED (July 2026) as a wife: she is named as the partner on her husband's\nmemorial-card record ([[alphonsus]], d. Oostende 11 March 1980), which puts the marriage on\nan independent record rather than on family memory alone. The card gives no dates of her\nown."});
FamilyTree.person({"id":"emma_vincke","name":"Emma Celesta Vincke","dates":"23 Jan 1880 Diksmuide – 6 Oct 1974 Oostende","confidence":"sup","surname":"Vincke","family":"vincke","born":"23 Jan 1880 Diksmuide","order":"1880-01-23","died":"6 Oct 1974 Oostende","branch":"Bundervoet","line":"van-iseghem","father":"lucien_vincke","mother":"ludovica_vanald","spouses":[{"id":"eduardus_vi","name":"Eduardus Van Iseghem","detail":"Oostende, 28 Sep 1907"}],"source":"Memorial card — Emma Celesta Vincke, d. Oostende 6 October 1974; gverdievel (Guy Verdievel)","note":"Lived to 94 — the longest-lived in this cluster — outliving her husband by nearly 30 years. Daughter of Lucien Vincke & Ludovica Vanalderweireldt.\n\nCORROBORATED (July 2026). A Familiekunde Vlaanderen Westkust memorial-card record gives\nher birth at Diksmuide on 23 January 1880, her death at Oostende on 6 October 1974, and\nher partner as Eduard Van Iseghem — every field as held here, and the marriage to\n[[eduardus_vi]] with it. She had rested on the gverdievel tree alone."});
