FamilyTree.person({"id":"gillis_sabbe","name":"Gillis Sabbe","dates":"~1440 – before 1520","confidence":"sup","surname":"Sabbe","family":"sabbe","born":"~1440","order":"1440","died":"before 1520","branch":"Bundervoet","line":"bostyn-cappaert","spouses":[{"name":"(wife unrecorded)"}],"source":"isavdw — Rijksarchief-sourced, with scan links","note":"FURTHEST CONFIRMED ANCESTOR of Renee & Leon — born ~1440, in the Burgundian Low Countries (era of Philip the Good / Charles the Bold, before the Habsburgs and before Columbus). Father of Judocus 'Joos' Sabbe (~1475). Top of the documented line; no parents recorded."});
