FamilyTree.person({"id":"judocus_sabbe","name":"Judocus Sabbe","dates":"~1667 – 5 Feb 1737 Oostkamp","confidence":"sup","surname":"Sabbe","family":"sabbe","born":"~1667","order":"1667","died":"5 Feb 1737 Oostkamp","branch":"Bundervoet","line":"bostyn-cappaert","father":"simon_sabbe","mother":"joanna_rotsaert_sabbe","spouses":[{"id":"anna_vannieuwenhuyse","name":"Anna Van Nieuwenhuyse","detail":"Oostkamp, 4 Aug 1700 — 3rd of his 4 marriages"}],"source":"isavdw — Rijksarchief-sourced, with scan links","note":"Father of Adriana Theresia Sabbe (1703). Married four times; farmer at Stuyvenberghe, Oostkamp. Parents Simon Sabbe (1627-1711) x Joanna Rotsaert."});
FamilyTree.person({"id":"judocus_sabbe_1475","name":"Judocus (Joos) Sabbe","dates":"~1475 – 1534","confidence":"sup","surname":"Sabbe","family":"sabbe","born":"~1475","order":"1475","died":"1534","branch":"Bundervoet","line":"bostyn-cappaert","father":"gillis_sabbe","spouses":[{"name":"NN Vandenberghe"}],"source":"isavdw — Rijksarchief-sourced, with scan links","note":"Born ~1475. Father of Petrus Sabbe (1504, Zwevegem). His own father is Gillis Sabbe (~1440), the deepest confirmed ancestor. Married an unnamed Vandenberghe."});
FamilyTree.person({"id":"judocus_vanrenterghem","name":"Judocus Van Renterghem","dates":"~1575 – 13 Feb 1641 Oostkamp","confidence":"sup","surname":"Van Renterghem","family":"vanrenterghem","born":"~1575","order":"1575","died":"13 Feb 1641 Oostkamp","occupation":"kerkmeester & dischmeester (churchwarden / poor-relief master)","branch":"Bundervoet","line":"bostyn-cappaert","father":"guillielmus_vanrenterghem","mother":"barbara_wittenheyns","spouses":[{"id":"appolonia_vandewoestijne","name":"Appolonia Vande Woestijne","detail":"Brugge (St-Catharina), 20 Jan 1602"}],"source":"isavdw — Rijksarchief-sourced, with scan links","note":"Source detail: Geneanet isavdw; Heemkring Oostkamp Wettelijke Passeringen; lanssens.be/patteeuw n9763; Sosa 6686\n\nGreat-grandfather of Maria Rups (1642). Churchwarden and poor-relief master (dischmeester) of Oostkamp, buried in the church, a Bruges citizen who bought the Lettenburgh farmstead (Moerbrugge). Rich property records 1612-1632. Parents Guillielmus Van Renterghem (~1530) x Barbara Wittenheyns (~1535)."});
FamilyTree.person({"id":"judocus_vi","name":"Judocus Franciscus Van Iseghem","dates":"19 Nov 1787 Oostende – 19 Apr 1832 Oostende","confidence":"sup","surname":"Van Iseghem","family":"vaniseghem","born":"19 Nov 1787 Oostende","order":"1787-11-19","died":"19 Apr 1832 Oostende","branch":"Bundervoet","line":"van-iseghem","spouses":[{"id":"victoria_engelsen","name":"Victoria Eugenia Engelsen","detail":"Oostende, 25 Mar 1810"}],"source":"gverdievel (Guy Verdievel)","note":"Married during the French Imperial period, when Oostende was annexed to France; died at 44.\n\nCHECKED AND REJECTED (July 2026). The corpus's best candidate for this record scores 33\nbits and is not him: an **Aalst** death act of 11 March 1869 for Josephus Hippolytus Van\nIseghem, whose father is *Constantinus Franciscus* Van Iseghem.\n\nThree things kill it. Our Judocus died at Oostende in **1832**, so he cannot be a named\nfather in an 1869 act. The forename is Constantinus Franciscus, not Judocus Franciscus —\nthe *Franciscus* they share is the commonest middle name in these registers. And Aalst is\nin Oost-Vlaanderen, sixty miles from the Oostende family this record belongs to.\n\nWhat produced the score was the surname plus that shared *Franciscus* plus a child's name.\nVan Iseghem is not rare enough in Oost-Vlaanderen for that to mean anything. Left ungrafted\nand uncited."});
FamilyTree.person({"id":"juliana_stroobandt","name":"Juliana Stroobandt","dates":"1839 Beernem (Oedelem in another source) – 11 Feb 1921 Oostkamp","confidence":"sup","surname":"Stroobandt","family":"stroobandt","born":"1839 Beernem (Oedelem in another source)","order":"1839","died":"11 Feb 1921 Oostkamp","branch":"Bundervoet","line":"bostyn-cappaert","father":"florentinus_stroobandt","mother":"rosalia_caeckaert","spouses":[{"id":"carel_cappaert","name":"Carel Louis Cappaert","detail":"Oostkamp, 30 Sep 1863"}],"source":"isavdw — Rijksarchief-sourced, with scan links; kathrynann; 1960dirk (Dirk Teerlinck)","note":"Married Carel Cappaert 1863 Oostkamp. Birth given as 13 Sep 1839 Beernem (kathrynann) or 12 Sep 1839 Oedelem (1960dirk) — adjacent villages. One of eleven Stroobandt children."});
