FamilyTree.person({"id":"ludovicus_p","name":"Ludovicus Paelinck","dates":"15 Jul 1660 Lochristi – 17 Apr 1720 Destelbergen","confidence":"sup","surname":"Paelinck","family":"paelinck","born":"15 Jul 1660 Lochristi","order":"1660-07-15","died":"17 Apr 1720 Destelbergen","branch":"Paelinck","line":"paelinck","father":"livinus1_p","mother":"elisabeth_t","spouses":[{"id":"petronella_v","name":"Petronella Verniers","detail":"Lochristi, Feb 1681"}],"source":"stefpaelinck (Stef Paelinck)","note":"Born in Lochristi (son of Livinus Paelinck & Elisabeth Temmerman); settled in Destelbergen, where he died."});
